def tiles(d,k):
    nr=(d.shape[0]+1)//(k+1); nc=(d.shape[1]+1)//(k+1)
    return [[d[r*(k+1):r*(k+1)+k,c*(k+1):c*(k+1)+k] for c in range(nc)] for r in range(nr)]
